#!/usr/bin/env python3
"""Convert temperatures between Celsius, Fahrenheit, and Kelvin."""

import argparse
import sys


def celsius_to_fahrenheit(c):
    return c * 9 / 5 + 32


def celsius_to_kelvin(c):
    return c + 273.15


def fahrenheit_to_celsius(f):
    return (f - 32) * 5 / 9


def kelvin_to_celsius(k):
    return k - 273.15


CONVERSIONS = {
    ("C", "F"): celsius_to_fahrenheit,
    ("C", "K"): celsius_to_kelvin,
    ("F", "C"): fahrenheit_to_celsius,
    ("K", "C"): kelvin_to_celsius,
}


def convert(value, from_unit, to_unit):
    from_unit = from_unit.upper()
    to_unit = to_unit.upper()

    if from_unit == to_unit:
        return value

    key = (from_unit, to_unit)
    if key not in CONVERSIONS:
        raise ValueError(f"Unknown conversion: {from_unit} -> {to_unit}")

    return CONVERSIONS[key](value)


def main():
    parser = argparse.ArgumentParser(description="Convert temperatures between Celsius, Fahrenheit, and Kelvin.")
    parser.add_argument("value", type=float, help="Temperature value to convert")
    parser.add_argument("from_unit", choices=["C", "F", "K", "c", "f", "k"], help="Source unit (C/F/K)")
    parser.add_argument("to_unit", choices=["C", "F", "K", "c", "f", "k"], help="Target unit (C/F/K)")

    args = parser.parse_args()
    result = convert(args.value, args.from_unit, args.to_unit)
    print(f"{args.value} {args.from_unit.upper()} = {result:.2f} {args.to_unit.upper()}")


if __name__ == "__main__":
    main()

